public static class ReviewBossModels {
 public static string Run(){var stage=new GameObject("Boss review");try{var cam=new GameObject("Review camera").AddComponent<Camera>();cam.transform.SetParent(stage.transform);cam.transform.position=new Vector3(5,-3,18);cam.transform.LookAt(new Vector3(5,-3,0));cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.08f,.1f,.13f);cam.orthographic=true;cam.orthographicSize=6.5f;cam.cullingMask=1<<29;var light=new GameObject("Key").AddComponent<Light>();light.transform.SetParent(stage.transform);light.type=LightType.Directional;light.intensity=2;light.transform.rotation=Quaternion.Euler(45,-145,0);light.cullingMask=1<<29;int i=0;foreach(string state in new[]{"Idle","Chase","Melee"})foreach(string name in new[]{"AngelKnight","Custodio de las dos hojas","Lancero de ceniza","Guardian de obsidiana"}){var go=UnityEngine.Object.Instantiate(Resources.Load<GameObject>("ExpeditionEnemies/"+name),stage.transform);foreach(var script in go.GetComponents<MonoBehaviour>())script.enabled=false;var animator=go.GetComponentInChildren<Animator>();animator.enabled=false;var clip=animator.runtimeAnimatorController.animationClips.FirstOrDefault(c=>c.name==state||c.name.EndsWith(state));if(!clip)throw new Exception("Missing clip "+name+" "+state);clip.SampleAnimation(animator.gameObject,clip.length*.45f);go.transform.position=new Vector3((i%4)*3.4f,-(i/4)*3.7f,0);i++;foreach(var t in go.GetComponentsInChildren<Transform>())t.gameObject.layer=29;}var rt=new RenderTexture(1600,1400,24);cam.targetTexture=rt;cam.Render();var old=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(1600,1400,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1400),0,0);tex.Apply();System.IO.File.WriteAllBytes("D:/67/CindersBackups/2026-11-07-angel-lab/bosses.png",tex.EncodeToPNG());RenderTexture.active=old;cam.targetTexture=null;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);return "12 poses rendered";}finally{UnityEngine.Object.DestroyImmediate(stage);}}
